INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 24, 'theory', 'Quiz: events');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 0, 'In what order does an event pass through the tree?', '["Bubbling → target → capturing", "Capturing → target → bubbling", "Target only", "Target → capturing"]', 1, 'Ordinary listeners fire on bubbling; capture: true subscribes to the capturing phase.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 1, 'How does event.target differ from event.currentTarget?', '["They do not", "target is always document", "target is where the event originated, currentTarget is whose handler is running now", "currentTarget is always window"]', 2, 'With delegation, target is the nested element and currentTarget is the container the handler is attached to.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 2, 'Why is closest used in delegation?', '["To climb from a nested target (such as an icon) to the button you need", "To remove an element", "To stop bubbling", "To make a copy"]', 0, 'The event comes from the deepest element under the cursor, so the needed ancestor is found with e.target.closest(selector).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 3, 'What does passive: true give a scroll or touch listener?', '["It forbids bubbling", "It removes the handler after the first call", "It makes the handler asynchronous", "The browser does not have to wait for the handler to start scrolling, but preventDefault cannot be called"]', 3, 'Passive listeners remove the scroll delay on mobile devices.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 4, 'Which property is better for hotkeys regardless of the keyboard layout?', '["key", "code", "keyCode", "char"]', 1, 'code describes the physical key (KeyS), key depends on the layout, and keyCode is obsolete.');
